UPDATE departments SET description='Справочный режим: предварительной продажи и закрепления места нет, покупка на месте. Среда–пятница 15:00–23:00, суббота–воскресенье 09:00–23:00; понедельник и вторник — выходные. Взрослый билет на 2 часа — 600 руб.; каждый следующий час — 270 руб. Ребёнок 3–7 лет включительно без отдельного места: 2 часа — 300 руб., следующий час — 150 руб. Тарифы с 30.09.2026. Бесплатное время после посещения не добавляется.' WHERE id='b1-male-floor-1';
UPDATE departments SET description='Справочный режим: предварительной продажи душевых кабинок нет, покупка на месте. Среда и четверг 12:30–21:30, суббота и воскресенье 09:00–21:00; понедельник, вторник и пятница — выходные. Взрослый: 1 час — 350 руб., 1,5 часа — 525 руб., 2 часа — 700 руб. Ребёнок 3–7 лет включительно без отдельной кабинки: 1 час — 170 руб., 1,5 часа — 255 руб., 2 часа — 340 руб.; до 3 лет бесплатно. Кабинка рассчитана на одного человека. Тарифы с 30.09.2026.' WHERE id IN ('b2-shower-large','b2-shower-small');
